#include <bits/stdc++.h>
using namespace std;

long long extended_gcd(long long a, long long b, long long &s, long long &t) {
    long long r0 = a, r1 = b;
    s = 1; long long s1 = 0;
    t = 0; long long t1 = 1;
    while (r1 != 0) {
        long long q = r0 / r1;
        long long r2 = r0 - q * r1;
        r0 = r1; r1 = r2;
        long long s2 = s1; s1 = s - q * s1; s = s2;
        long long t2 = t1; t1 = t - q * t1; t = t2;
    }
    return r0;
}

vector<long long> factorial_coeffs(int n, long long M) {
    vector<long long> coeffs(n + 1, 0);
    coeffs[n] = 1;
    for (int k = n - 1; k >= 0; --k) {
        coeffs[k] = (coeffs[k + 1] * (k + 1)) % M;
        if (coeffs[k] == 0) break;
    }
    return coeffs;
}

long long compute_app(int n, long long M) {
    vector<vector<vector<long long>>> K;
    K.push_back({{1}});
    for (int i = 0; i < n - 1; ++i) {
        auto &prev_layer = K[i];
        int size_prev = (int)prev_layer.size();
        int row_size = (int)prev_layer[0].size();
        vector<vector<long long>> new_layer(size_prev + i + 1, vector<long long>(i + 2, 0));
        for (int j = 0; j < size_prev; ++j) {
            for (int k = 0; k < row_size; ++k) {
                for (int h = 0; h <= i; ++h) {
                    new_layer[j + h][k] = (new_layer[j + h][k] + prev_layer[j][k]) % M;
                }
                new_layer[j + i + 1][i + 1] = (new_layer[j + i + 1][i + 1] + prev_layer[j][k]) % M;
            }
        }
        K.push_back(new_layer);
    }
    vector<long long> C = factorial_coeffs(n, M);
    long long total_sum = 0;
    for (int i = 1; i < n; ++i) {
        auto &current_layer = K[i];
        int ni = (int)current_layer.size();
        int mi = (int)current_layer[0].size();
        vector<vector<long long>> S(ni, vector<long long>(mi, 0));
        for (int j = 0; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                S[j][k] = current_layer[j][k];
            }
        }
        for (int j = 0; j < ni; ++j) {
            for (int k = mi - 2; k >= 0; --k) {
                S[j][k] = (S[j][k] + S[j][k + 1]) % M;
            }
        }
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi; ++k) {
                S[j][k] = (S[j][k] + S[j - 1][k]) % M;
            }
        }
        long long s_value = 0;
        for (int j = 1; j < ni; ++j) {
            for (int k = 0; k < mi - 1; ++k) {
                s_value += (current_layer[j][k] * S[j - 1][k + 1]) % M;
                s_value %= M;
            }
        }
        long long c = C[i + 1];
        s_value = (s_value * c) % M;
        total_sum = (total_sum + s_value) % M;
    }
    return total_sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; long long m;
    cin >> n >> m;
    cout << compute_app(n, m) << "\n";
    return 0;
}

